# Code generated by Claude
"""
Screenshots of the status panel for every phase of a recorded demo episode (and of the phases before the robot moves).

    python experiments/panel_stills.py RECORDING_DIR OUT_DIR

Replays the recording in the video's "viewer" mode (src/replay.py) but renders a picture only at the first frame of each phase (the text of the label before " ["), saves the whole
picture and the panel alone as PNG (<out>/stills_still_<label>.png, stills_panel_<label>.png) and throws the tiny video away. It uses the same renderer as the demo video, so the
panel is the video's panel.
"""

import argparse
import json
import os
import re
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
os.environ.setdefault("MUJOCO_GL", "egl")

import src.replay as replay_mod  # noqa: E402
from demo_video import intro_for  # noqa: E402


class NullWriter:
    def write(self, frame):
        pass

    def release(self):
        pass


def main(args):
    rec, out = Path(args.recording), Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    meta = json.loads((rec / "meta.json").read_text())
    seen, stills = set(), {}
    for l in meta["labels"]:
        key = l["label"].split(" [")[0].split("  (+")[0]
        if key not in seen:
            seen.add(key)
            tick = l["tick"]
            tick = tick + ((4 - tick) % 5)                      # the first rendering tick of the 30 Hz video at or after the phase start
            stills[re.sub(r"[^A-Za-z0-9]+", "_", key).strip("_")] = tick
    intro = [{**e, "seconds": 1 / 30} for e in intro_for(rec)]
    print(f"{len(stills)} phases: " + ", ".join(f"{k}@{v}" for k, v in stills.items()), flush=True)
    replay_mod.open_video = lambda path, fps, size, codec="mp4v", quality=None: NullWriter()
    r = replay_mod.replay_run(rec, out_dir=out, video="viewer", hz=30.0, name="stills", quiet=True, intro=intro, still_ticks=stills, render_at_ticks=set(stills.values()))
    print(f"replay ok {r['ok']} ticks {r['ticks']} frames {r['frames_rendered']}", flush=True)
    return 0 if r["ok"] else 1


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("recording")
    ap.add_argument("out")
    sys.exit(main(ap.parse_args()))
